  <script>
    (async function() {
      const CONTRACT = '0x7e5029837a43c547cdcea2107a1e07e30d68c6d6';
      const TOKEN_ID = 4;
      const RPC = (window.RPC_URLS || {}).ethereum;
      const ABI = ['function tokenURI(uint256 tokenId) view returns (string)'];

      try {
        const provider = new ethers.JsonRpcProvider(RPC);
        const contract = new ethers.Contract(CONTRACT, ABI, provider);
        const uri = await contract.tokenURI(TOKEN_ID);

        let metadata;
        if (uri.startsWith('data:application/json;base64,')) {
          metadata = JSON.parse(atob(uri.split(',')[1]));
        } else if (uri.startsWith('data:application/json,')) {
          metadata = JSON.parse(decodeURIComponent(uri.split(',')[1]));
        } else {
          const res = await fetch(uri);
          metadata = await res.json();
        }

        const animUrl = metadata.animation_url || metadata.animationUrl;
        if (!animUrl) throw new Error('No animation URL in metadata');

        const wrap = document.querySelector('.onchain-frame-wrap');
        wrap.innerHTML = '';
        const iframe = document.createElement('iframe');
        iframe.src = animUrl;
        iframe.title = 'Prozac Youth';
        iframe.setAttribute('sandbox', 'allow-scripts');
        iframe.setAttribute('allow', 'accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture');
        wrap.appendChild(iframe);
      } catch (e) {
        console.error('On-chain load failed:', e);
        document.getElementById('onchain-status').textContent = 'Failed to load from chain.';
      }
    })();
  </script>

